<?php declare(strict_types=1); require_once __DIR__.'/../../config/db.php'; require_once __DIR__.'/../../lib/session.php'; require_once __DIR__.'/../../lib/auth.php'; use function App\Auth\{require_admin,csrf_token}; start_secure_session();require_admin();$pdo=db();$csrf=csrf_token();$rows=$pdo->query("SELECT setting_key,setting_value FROM whatsapp_bridge_settings WHERE setting_key LIKE 'trigger_%' OR setting_key LIKE 'condition_%' OR setting_key LIKE 'action_%'")->fetchAll(PDO::FETCH_KEY_PAIR);$on=fn($k,$d=false)=>($rows[$k]??($d?'1':'0'))==='1'; ?>
<!doctype html><html><head><meta charset="utf-8"><title>WhatsApp workflow controls</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>.flow{display:grid;grid-template-columns:1fr 40px 1fr 40px 1fr;gap:12px;align-items:stretch}.arrow{display:grid;place-items:center;font-size:24px;color:#6c757d}.card{height:100%}@media(max-width:700px){.flow{grid-template-columns:1fr}.arrow{transform:rotate(90deg)}}</style></head><body class="bg-light"><main class="container py-4"><a href="/admin/index.php">← Admin</a><h1 class="h3 mt-3">WhatsApp workflow controls</h1><p class="text-secondary">Choose the triggers, gates, and actions for new WhatsApp intake messages.</p><form id="workflow"><div class="flow"><section class="card shadow-sm"><div class="card-body"><h2 class="h5">1. Trigger</h2><p class="small text-secondary">What starts a workflow?</p><label class="form-check"><input class="form-check-input" type="checkbox" name="trigger_mention" <?=$on('trigger_mention',true)?'checked':''?>> Message contains <code>@ridebot</code></label><label class="form-check"><input class="form-check-input" type="checkbox" name="trigger_all_group" <?=$on('trigger_all_group')?'checked':''?>> Any Test rides group message</label><label class="form-check"><input class="form-check-input" type="checkbox" name="trigger_confirm" <?=$on('trigger_confirm',true)?'checked':''?>> Direct reply <code>CONFIRM</code> / <code>CANCEL</code></label></div></section><div class="arrow">→</div><section class="card shadow-sm"><div class="card-body"><h2 class="h5">2. Wait / condition</h2><p class="small text-secondary">The bot waits until these are true.</p><label class="form-check"><input class="form-check-input" type="checkbox" name="condition_format" <?=$on('condition_format',true)?'checked':''?>> Type, route, and contact are present</label><label class="form-check"><input class="form-check-input" type="checkbox" name="condition_confirm" <?=$on('condition_confirm',true)?'checked':''?>> Sender confirms the preview</label></div></section><div class="arrow">→</div><section class="card shadow-sm"><div class="card-body"><h2 class="h5">3. Actions</h2><p class="small text-secondary">What happens after the conditions pass?</p><label class="form-check"><input class="form-check-input" type="checkbox" name="action_private_dm" <?=$on('action_private_dm',true)?'checked':''?>> Private status / clarification DM</label><label class="form-check"><input class="form-check-input" type="checkbox" name="action_queue" <?=$on('action_queue',true)?'checked':''?>> Add to admin review queue</label><label class="form-check"><input class="form-check-input" type="checkbox" name="action_post_group" <?=$on('action_post_group',true)?'checked':''?>> Post formatted ride to Test rides</label><label class="form-check"><input class="form-check-input" type="checkbox" name="action_create_ride" <?=$on('action_create_ride',true)?'checked':''?>> Create public Bot ride</label></div></section></div><div class="mt-4"><button class="btn btn-primary">Save workflow</button><a class="btn btn-outline-secondary" href="/admin/whatsapp_intakes.php">Open intake queue</a><span id="saved" class="ms-2 text-success"></span></div></form></main><script>document.querySelector('#workflow').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.csrf='<?=htmlspecialchars($csrf)?>';let r=await fetch('/api/admin/whatsapp_workflow.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});document.querySelector('#saved').textContent=r.ok?'Saved':'Could not save'}</script></body></html>
